head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 acp_autoComplete1 의 ref 부분을 확인한다.
    //1. Check the ref section of acp_autoComplete1 in the Source tab or Property tab.
    //Verify step 1. ref = 'data: dataList1.col2'
    //Test step 2. 브라우저에서 name1 또는 nmae2 컬럼의 데이터를 임의로 선택한다. (예 : 'b')
    //2. Select arbitrarily the data in the name1 or nmae2 column in the browser. (E.g. 'b')
    //Verify step 2. Name2 and AutoComplete of selected data are kept as 'b-2'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView2_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('acp_autoComplete1_label').innerText == 'b-2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. AutoComplete 에서 'b-2' -> 'b-1' 로 변경한다.
    //3. In AutoComplete, change it to 'b-2' -> 'b-1'.
    //Verify step 3. The selected name2 column in gridView is also changed to 'b-2' -> 'b-1'. (No matter how you change AutoComplete in previous versions)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('acp_autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('acp_autoComplete1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_1_1').innerText == 'b-1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.t1 = [{
            "col1": "a",
            "col2": "a-2",
            "rowStatus": "C"
        },
        {
            "col1": "b",
            "col2": "b-2",
            "rowStatus": "C"
        },
        {
            "col1": "a",
            "col2": "a-2",
            "rowStatus": "C"
        }
    ];
    window.t2 = [{
            "val": "a-1",
            "label": "a-1",
            "gubun": "a"
        },
        {
            "val": "a-2",
            "label": "a-2",
            "gubun": "a"
        },
        {
            "val": "a-3",
            "label": "a-3",
            "gubun": "a"
        },
        {
            "val": "b-1",
            "label": "b-1",
            "gubun": "b"
        },
        {
            "val": "b-2",
            "label": "b-2",
            "gubun": "b"
        }
    ];
    itemset1.setJSON(t2);
    dataList1.setJSON(t1);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 03-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
